(()=>{"use strict";(()=>{const t=document.querySelector("#timer-hours"),e=document.querySelector("#timer-minutes"),n=document.querySelector("#timer-seconds");let o;o=setInterval((()=>{let r=(()=>{let t=(new Date("9 january 2025").getTime()-(new Date).getTime())/1e3;return{timeRemaning:t,hours:Math.floor(t/60/60),minutes:Math.floor(t/60%60),seconds:Math.floor(t%60)}})();r.timeRemaning>0?(t.textContent=r.hours.toString().padStart(2,"0"),e.textContent=r.minutes.toString().padStart(2,"0"),n.textContent=r.seconds.toString().padStart(2,"0")):(console.log("Остановите"),clearInterval(o))}),1e3)})()})();